sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var ritm = steps('400').request_item;          // RITM sys_id from step 4
  var appr = new GlideRecord('sysapproval_approver');
  appr.addQuery('sysapproval', ritm);
  appr.addQuery('state', 'requested');
  appr.query();
  if (!appr.next()) { stepResult.setFailed('no pending approval for ' + ritm); return; }
  if (appr.approver == gs.getUserID()) { stepResult.setFailed('SoD violated: requester == approver'); return; }
  appr.setValue('state', 'approved');
  appr.update();
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var ritm = steps('400').request_item;
  var gr = new GlideRecord('sc_req_item');
  if (!gr.get(ritm)) { stepResult.setFailed('RITM not found'); return; }
  var expectIp = gs.getProperty('x_infoblox_ddi.test_ip', '10.10.8.12');
  // The Flow writes the allocated IP + gate verdict to work notes / a field.
  var notes = gr.getValue('work_notes') || '';
  var ok = notes.indexOf(expectIp) > -1 && notes.toLowerCase().indexOf('pass') > -1;
  stepResult.setOutputMessage('work_notes checked for ' + expectIp + ' and gate pass');
  ok ? stepResult.setSuccess() : stepResult.setFailed('allocated IP / gate-pass not found in work notes');
})(outputs, steps, stepResult);

table = sc_req_item
conditions = sys_id={RITM from step 4}
assert = state = 3 (Closed Complete)
